begin;
select set_config('request.jwt.claim.sub',(select id::text from public.profiles where is_root),true);
update public.family_settings set endorsements_enabled=true,restrict_gender_chat=false,chat_enabled=true;
update family_private.member_details set phone='+966500009101',gender='male',full_name='مرتضى علي سلمان اختبار' where id=auth.uid();
create temp table social_fixture as select gen_random_uuid() as applicant;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) select applicant,applicant::text||'@example.invalid',now(),jsonb_build_object('full_name','محمد علي حسن اختبار','phone','+966500009102','gender','male','sponsor_hint','+966500009101') from social_fixture;
create temp table social_results as select exists(select 1 from family_private.endorsements where applicant_id=(select applicant from social_fixture) and sponsor_id=auth.uid()) as signup_notification;
select public.endorse_action('approve',jsonb_build_object('id',(select id from family_private.endorsements where applicant_id=(select applicant from social_fixture)),'confirm',true));
alter table social_results add column endorsement_activated boolean;
update social_results set endorsement_activated=(select status='active' from public.profiles where id=(select applicant from social_fixture));
create temp table group_fixture as select (public.group_action('create',jsonb_build_object('title','مجموعة اختبار مؤقتة','kind','group','members',jsonb_build_array((select applicant from social_fixture))))#>>'{}')::uuid as id;
select public.group_action('send',jsonb_build_object('id',(select id from group_fixture),'message','GROUP_ONLY_TEST'));
alter table social_results add column group_message_saved boolean,add column group_not_in_public boolean,add column avatar_only_own boolean,add column event_scheduled boolean;
update social_results set group_message_saved=public.group_action('read',jsonb_build_object('id',(select id from group_fixture)))::text like '%GROUP_ONLY_TEST%',group_not_in_public=public.chat_read(null,null)::text not like '%GROUP_ONLY_TEST%';
create temp table event_fixture as select(public.group_action('create',jsonb_build_object('title','حدث اختبار مستقبلي','kind','event','starts_at',now()+interval '1 day','ends_at',now()+interval '2 days','members','[]'::jsonb))#>>'{}')::uuid as id;
update social_results set event_scheduled=exists(select 1 from jsonb_array_elements(public.group_action('list'))g where g->>'id'=(select id::text from event_fixture) and (g->>'open_now')::boolean=false);
select set_config('request.jwt.claim.sub',(select applicant::text from social_fixture),true);
select public.account_action('phone_request','{"phone":"+966500009103"}');
select set_config('request.jwt.claim.sub',(select id::text from public.profiles where is_root),true);
select public.account_action('phone_approve',jsonb_build_object('id',(select id from family_private.phone_requests where member_id=(select applicant from social_fixture))));
alter table social_results add column phone_approval_saved boolean;
update social_results set phone_approval_saved=(select phone='+966500009103' from family_private.member_details where id=(select applicant from social_fixture));
select signup_notification,endorsement_activated,group_message_saved,group_not_in_public,event_scheduled,phone_approval_saved from social_results;
rollback;
